const renderBeforeNativeFrames=$('renderVideo').onclick;$('renderVideo').onclick=async()=>{if(!window.studioDesktop?.beginFrameExport)return renderBeforeNativeFrames();$('exportDialog').close();try{return await renderNativeFrames({range:typeof readExportRange==='function'?readExportRange():null})}catch(e){toast(e.message||'Export failed.')}};
